import { USERS, expect, test } from "../../fixtures";

test.describe("Sign in", () => {
  test("Wrong password is rejected without revealing which field was wrong", { tag: "@AUTH-02" }, async ({ request }) => {
    // When I sign in as "member@northwind.test" with password "wrong-password"
    const response = await request.post("/api/auth/login", {
      data: { email: USERS.member, password: "wrong-password" },
    });
    const bodyText = await response.text();

    // Then the response status is 401
    expect(response.status(), bodyText).toBe(401);

    // And the error code is "invalid_credentials"
    const body = JSON.parse(bodyText);
    expect(body?.error?.code, bodyText).toBe("invalid_credentials");
  });
});
